export const CLI_CONTROL_COMMANDS: ReadonlySet<string> = new Set([
  'open',
  'stop',
  'status',
  'update',
  'version',
  'wait',
  'variants',
  'evidence',
  'reference',
  'profile',
  'context',
  'auth',
  'mcp',
  '__serve',
  '__hub',
]);

export const isCliControlCommand = (command: string | undefined): boolean =>
  command !== undefined && CLI_CONTROL_COMMANDS.has(command);

export const normalizeCliInvocation = (args: string[]): string[] => {
  const first = args[0];
  if (!first) return ['open'];
  if (['--help', '-h', '--version', '-v'].includes(first)) return args;
  if (first === 'agent') return ['open', ...args.slice(1)];
  if (first.startsWith('-'))
    return ['open', ...args.map((arg) => (arg === '-d' ? '--debug' : arg))];
  return args;
};
